import type { Locale } from './locales'

/**
 * Learner-facing content for the interactive experiments' prediction banks.
 * Stable prediction/option IDs and all observation predicates remain in the
 * experiment modules; this catalogue contains presentation copy only.
 */
type Copy = {
  question: string
  task: string
  options: Record<string, string>
  explanation: string
}
type ExperimentId = 'space-vs-time' | 'displacement3d' | 'pendulum' | 'newtonian' | 'force-lab' | 'momentum-collisions' | 'projectile' | 'circular-orbits' | 'moving-clocks' | 'two-perspectives' | 'length-contraction' | 'gravity-clocks' | 'geodesic-motion' | 'evolving-space'
type Catalogue = Partial<Record<string, Copy>>
type LocalizedCatalogues = Record<Exclude<Locale, 'en'>, Record<ExperimentId, Catalogue>>

const id: LocalizedCatalogues['id'] = {
  'space-vs-time': {
    rest: { question: 'Anda mengatur kecepatan menjadi nol lalu menjalankan jam. Seperti apa grafik posisi–waktu?', task: 'Atur v = 0 dan biarkan jam berjalan setidaknya 3 detik.', options: { flat: 'Garis horizontal: posisi tetap sementara waktu terus berjalan', dot: 'Satu titik: tidak ada perubahan, jadi waktu berhenti', vertical: 'Garis vertikal', rising: 'Garis yang menanjak' }, explanation: 'Benda tidak bergerak, tetapi jam tetap berjalan: grafik memanjang ke kanan (waktu), bukan ke atas atau bawah (posisi). Berhenti bergerak dalam ruang tidak menghentikan jam. Dalam x(t) = x₀ + v·t, jika v = 0 maka x = x₀ untuk setiap nilai t.' },
    double: { question: 'Anda menjalankan eksperimen dua kali: pertama pada suatu kecepatan, lalu pada dua kali kecepatan itu. Apa yang terjadi pada garis grafik?', task: 'Lakukan dua percobaan, misalnya 1 m/s dan 2 m/s, masing-masing dipertahankan setidaknya 3 detik.', options: { steeper: 'Kemiringannya menjadi dua kali lebih besar', shifted: 'Garis bergeser ke atas tetapi kemiringannya tetap', same: 'Tampilannya sama, hanya berakhir lebih cepat', shallower: 'Kemiringannya menjadi setengah' }, explanation: 'Kemiringan grafik posisi–waktu adalah kecepatan: kemiringan = Δx / Δt = v. Menggandakan v menggandakan jarak yang ditempuh setiap detik, sehingga garis naik dua kali lebih cepat. Mengubah x₀ justru menggeser garis tanpa mengubah kemiringannya.' },
    reverse: { question: 'Dalam satu percobaan, mulai dari x₀ = 0 dengan kecepatan +2 m/s selama 3 detik, lalu tanpa menghentikan jam ubah kecepatan menjadi −2 m/s selama 3 detik lagi. Berapa perpindahan Δx dan jarak tempuhnya?', task: 'Mulai pada +2 m/s. Setelah sekitar 3 detik, saat jam masih berjalan, geser pengatur kecepatan ke −2 m/s dan lanjutkan 3 detik. Jangan tekan Reset.', options: { 'zero-twelve': 'Δx = 0 m, jarak = 12 m', 'both-twelve': 'Δx = 12 m, jarak = 12 m', 'both-zero': 'Δx = 0 m, jarak = 0 m', 'twelve-zero': 'Δx = 12 m, jarak = 0 m' }, explanation: 'Perpindahan hanya membandingkan posisi akhir dan awal: Δx = ∫v dt, sehingga gerak maju dan mundur saling meniadakan. Jarak adalah panjang lintasan, s = ∫|v| dt, dan tidak pernah berkurang. Keduanya sama hanya jika gerak tidak pernah berbalik arah.' },
    'moving-observer': { question: 'Benda diam di lintasan (v = 0). Pengamat kedua bergerak sepanjang lintasan dengan u = +2 m/s. Seperti apa grafik posisi–waktu benda dalam koordinat pengamat x′?', task: 'Tekan Reset, atur posisi awal x₀ = +6 m, v = 0, dan kecepatan pengamat u = +2 m/s. Jalankan jam setidaknya 3 detik dan amati garis putus-putus oranye.', options: { flat: 'Garis horizontal: benda diam, jadi diam bagi semua orang', down: 'Garis menurun dengan kemiringan −2 m/s', up: 'Garis menaik dengan kemiringan +2 m/s', undefined: 'Tidak ada garis: pengamat bergerak tidak dapat menentukan posisi benda' }, explanation: 'Pengamat memberi label setiap peristiwa dengan x′ = x − u·t. Karena x = x₀ tetap, x′ = x₀ − u·t adalah garis lurus dengan kemiringan v′ = v − u = −u (−2 m/s untuk u = +2 m/s). Bagi pengamat, benda bergerak mundur melewatinya. Kedua deskripsi benar: dalam fisika Galilea, keadaan diam selalu relatif terhadap kerangka acuan. Keduanya tetap sepakat bahwa waktu t′ = t.' },
  },
  displacement3d: {
    'round-trip': { question: 'Sebuah drone terbang 3 m ke timur, 4 m ke utara, dan 2 m ke atas, lalu kembali lurus ke titik lepas landas. Berapa perpindahannya? (Timur = +x, utara = +y, atas = +z.)', task: 'Buat perjalanan sedikitnya tiga langkah yang kembali ke titik awal, atau muat “Round trip”, lalu baca perpindahannya.', options: { zero: 'Nol', nine: '9 m', eighteen: 'Sekitar 14,4 m (seluruh penerbangan)', five: '5,4 m' }, explanation: 'Perpindahan hanya membandingkan posisi akhir dengan posisi awal. Drone berakhir di tempat semula, jadi perpindahannya nol. Jarak tempuhnya tidak nol: 3 + 4 + 2 m saat pergi dan √29 ≈ 5,4 m saat kembali, total sekitar 14,4 m. Jarak adalah panjang lintasan; perpindahan adalah panah lurus dari awal ke akhir.' },
    diagonal: { question: 'Anda bergerak 3 m sepanjang x, lalu 4 m sepanjang y, kemudian 12 m sepanjang z. Berapa jarak lurus titik akhir dari titik awal?', task: 'Lakukan perjalanan tersebut atau muat “3, 4, 12 diagonal”, lalu baca besar perpindahannya.', options: { nineteen: '19 m', thirteen: '13 m', twelve: '12 m', seventeen: 'Sekitar 17 m' }, explanation: 'Teorema Pythagoras juga berlaku dalam tiga dimensi: |Δr| = √(3² + 4² + 12²) = √169 = 13 m. Lantai memberi √(3² + 4²) = 5 m, lalu √(5² + 12²) = 13 m. Nilai 19 m adalah jarak yang ditempuh sepanjang sisi-sisi lintasan.' },
    shift: { question: 'Anda memindahkan titik asal sistem koordinat ke tempat lain. Apa yang terjadi pada perpindahan benda?', task: 'Buat perjalanan, lalu pindahkan titik asal sistem koordinat kedua dan bandingkan kedua kumpulan angka.', options: { unchanged: 'Tetap persis sama', shifted: 'Berubah sebesar perpindahan titik asal', zero: 'Menjadi nol', grows: 'Menjadi lebih panjang' }, explanation: 'Memindahkan titik asal mengubah semua posisi dengan jumlah yang sama. Namun perpindahan adalah selisih dua posisi, sehingga pergeseran itu saling menghapus: Δr′ = (r_akhir − O) − (r_awal − O) = Δr. Letak titik asal adalah pilihan; seberapa jauh dan ke arah mana benda bergerak bukan pilihan.' },
    rotation: { question: 'Anda memutar sumbu koordinat sebesar 30°. Besaran mana yang tetap sama?', task: 'Buat perjalanan, lalu putar sumbu sistem koordinat kedua dan bandingkan kedua kumpulan angka.', options: { x: 'Komponen x dari perpindahan', length: 'Panjang perpindahan, |Δr|', all: 'Ketiga komponennya', none: 'Tidak ada: semuanya berubah' }, explanation: 'Memutar sumbu mengubah komponen (Δx′, Δy′, Δz′), tetapi panah geometrisnya tidak berubah sehingga panjangnya tetap: Δx′² + Δy′² + Δz′² = Δx² + Δy² + Δz². Besaran yang disepakati semua sistem koordinat disebut invarian. “Jam berbeda” dan “Ruang dan waktu versus ruang-waktu” memiliki gagasan serupa dalam ruang-waktu: interval.' },
    triangle: { question: 'Dapatkah jarak yang Anda tempuh lebih pendek daripada besar perpindahan Anda?', task: 'Buat perjalanan dengan dua langkah atau lebih yang tidak berada pada satu garis lurus, lalu bandingkan jarak dengan |Δr|.', options: { shortcut: 'Ya, jika mengambil jalan pintas', never: 'Tidak pernah: garis lurus adalah lintasan terpendek', curved: 'Hanya jika lintasannya melengkung', 'three-d': 'Hanya dalam tiga dimensi' }, explanation: 'Ketaksamaan segitiga, |Δr₁ + Δr₂| ≤ |Δr₁| + |Δr₂|, menyatakan bahwa garis lurus adalah rute terpendek antara dua titik dalam ruang Euclidean. Jadi jarak ≥ |perpindahan|, dengan kesamaan hanya untuk lintasan lurus. Dalam ruang-waktu, ketaksamaannya berbalik: garis dunia lurus antara dua peristiwa memiliki waktu wajar terpanjang.' },
  },
  pendulum: {
    length: { question: 'Anda membuat tali pendulum empat kali lebih panjang. Waktu untuk satu ayunan penuh (pergi dan kembali)…', task: 'Dengan ayunan kecil (20° atau kurang), ukur periode pada satu panjang, lalu pada panjang empat kali lipat, misalnya 0,5 m dan 2,0 m.', options: { same: 'Tetap sama', double: 'Menjadi dua kali lipat', four: 'Menjadi empat kali lipat', half: 'Menjadi setengah' }, explanation: 'Untuk ayunan kecil, periode T = 2π√(L/g). Panjang empat kali lipat menghasilkan periode √4 = 2 kali lipat. Karena itulah jam bandul besar biasanya memiliki pendulum yang panjang.' },
    mass: { question: 'Anda mengganti bandul dengan bandul yang massanya sepuluh kali lebih besar, pada tali yang sama. Periodenya…', task: 'Pertahankan panjang dan sudut ayunan, lalu ukur periode dengan bandul ringan dan bandul setidaknya lima kali lebih berat.', options: { shorter: 'Lebih singkat: bandul berat jatuh lebih cepat', same: 'Tetap sama', longer: 'Lebih lama: bandul berat lebih sulit digerakkan', stops: 'Bandul berat hampir tidak berayun' }, explanation: 'Bandul yang lebih berat ditarik gravitasi lebih kuat, tetapi juga lebih sulit dipercepat dengan faktor yang persis sama, sehingga massanya saling menghapus. Ini berkaitan dengan kesetaraan massa gravitasi dan massa inersia, yang menjadi dasar prinsip ekuivalensi dalam relativitas umum.' },
    moon: { question: 'Jam pendulum yang akurat di Bumi dibawa ke Bulan, tempat gravitasi sekitar 1/6 gravitasi Bumi. Jam tersebut…', task: 'Ukur periode pendulum yang sama (panjang sama) di Bumi dan Bulan, lalu bandingkan kedua jam.', options: { slow: 'Berjalan sekitar 2,5 kali terlalu lambat', six: 'Berjalan 6 kali terlalu lambat', same: 'Tetap menunjukkan waktu dengan tepat', fast: 'Berjalan terlalu cepat' }, explanation: 'T = 2π√(L/g) bertambah sebanding dengan 1/√g. Karena gravitasi Bulan sekitar seperenam gravitasi Bumi, setiap ayunan memerlukan sekitar √6 ≈ 2,46 kali lebih lama. Jam pendulum pun kehilangan waktu. Ini bukan berarti waktu itu sendiri melambat; periode pendulum bergantung pada gravitasi.' },
    'time-itself': { question: 'Jadi, apakah waktu itu sendiri berlalu lebih lambat di Bulan?', task: 'Ukur pendulum yang sama di Bumi dan Bulan, lalu bandingkan jam pendulum dengan jam atom.', options: { yes: 'Ya: jam pendulum yang lambat membuktikannya', no: 'Tidak: pendulum bergantung pada gravitasi; jam atom di Bulan justru berjalan sedikit lebih cepat', unknown: 'Tidak ada cara untuk mengetahuinya', pendulums: 'Hanya untuk pendulum: waktu berbeda bagi setiap jenis jam' }, explanation: 'Pendulum mengukur pengaruh gravitasi sekaligus waktu: iramanya bergantung pada g. Jam atom, yang mendefinisikan detik, tidak bekerja seperti itu. Jam atom di Bulan berjalan sedikit lebih cepat, sekitar 56 mikrodetik per hari, karena gravitasinya lebih lemah. Jam yang baik seharusnya sepakat ketika dibandingkan bersama; jam yang berbeda mungkin juga mengukur pengaruh lain.' },
    amplitude: { question: 'Galileo berpendapat bahwa periode pendulum tidak bergantung pada lebar ayunannya. Jika dilepas dari 90° alih-alih 5°, periodenya…', task: 'Ukur pendulum yang sama saat dilepas dari 90° (atau lebih) dan dari 10° atau kurang.', options: { same: 'Sama', longer: 'Sekitar 18% lebih lama', shorter: 'Sekitar 18% lebih singkat', double: 'Sekitar dua kali lebih lama' }, explanation: 'Gaya pemulih sebanding dengan sin θ, bukan θ, sehingga ayunan lebar lebih lambat. Pada sudut awal 90°, periode tepatnya sekitar 1,180 kali periode pendekatan sudut kecil. Pembuat jam menjaga ayunan tetap kecil dan konstan agar ketepatannya terjaga.' },
  },
  newtonian: {
    mass: { question: 'Anda mendorong dua kereta dengan gaya resultan yang sama. Massa salah satu kereta dua kali lebih besar. Apa yang terjadi pada percepatannya?', task: 'Jalankan model dua kali dengan gaya sama dan dua massa berbeda. Bandingkan percepatan yang terukur.', options: { same: 'Keduanya mengalami percepatan yang sama', half: 'Kereta yang lebih berat mengalami setengah percepatan', double: 'Kereta yang lebih berat mengalami dua kali percepatan' }, explanation: 'Hukum kedua Newton adalah a = F_net/m. Dengan gaya resultan yang sama, menggandakan massa membuat percepatan menjadi setengah. Massa mengukur kelembaman, yaitu resistansi terhadap perubahan gerak.' },
    force: { question: 'Anda menggandakan gaya resultan pada kereta yang sama. Apa yang terjadi pada percepatannya?', task: 'Pertahankan massa, lalu jalankan model dengan dua nilai gaya resultan dan bandingkan percepatannya.', options: { same: 'Tetap sama', half: 'Menjadi setengah', double: 'Menjadi dua kali lipat' }, explanation: 'Untuk massa tetap, percepatan berbanding lurus dengan gaya resultan. Menggandakan gaya resultan menggandakan percepatan.' },
  },
  projectile: {
    'best-angle': { question: 'Tanpa hambatan udara, sudut peluncuran mana yang membuat bola menempuh jarak horizontal terjauh di tanah datar?', task: 'Atur ketinggian 0 dan matikan hambatan udara. Luncurkan pada 45°, sudut lebih rendah, dan sudut lebih tinggi dengan kecepatan sama.', options: { '30': '30°', '45': '45°', '60': '60°', '90': 'Tegak lurus ke atas (90°)' }, explanation: 'Jangkauan R = v² sin(2θ)/g maksimum ketika 2θ = 90°, sehingga θ = 45°. Sudut lebih rendah memberi kecepatan horizontal lebih besar tetapi waktu di udara lebih singkat; sudut lebih tinggi memberi waktu lebih lama tetapi kecepatan horizontal lebih kecil. Sudut yang sama jauhnya dari 45°, seperti 30° dan 60°, menghasilkan jangkauan sama.' },
    drop: { question: 'Sebuah bola dilempar horizontal dari dinding pada saat yang sama dengan bola identik yang dijatuhkan dari ketinggian sama. Mana yang lebih dahulu menyentuh tanah?', task: 'Atur sudut 0°, ketinggian minimal 5 m, matikan hambatan udara, centang “Also drop a ball”, lalu luncurkan.', options: { thrown: 'Bola yang dilempar', dropped: 'Bola yang dijatuhkan', together: 'Keduanya menyentuh tanah bersamaan', depends: 'Bergantung pada seberapa kuat lemparannya' }, explanation: 'Gerak horizontal dan vertikal saling bebas. Kedua bola mulai tanpa kecepatan vertikal dan jatuh dengan gravitasi yang sama, sehingga selalu berada pada ketinggian sama. Bola yang dilempar hanya bergerak ke samping. Galileo menjelaskan prinsip ini.' },
    moon: { question: 'Astronaut melakukan lemparan yang sama di Bulan, dengan gravitasi sekitar 1/6 gravitasi Bumi. Seberapa jauh bola bergerak?', task: 'Tanpa hambatan udara dan dari ketinggian 0, lakukan lemparan dengan kecepatan dan sudut sama di Bumi dan Bulan.', options: { same: 'Jarak yang sama', root: 'Sekitar 2,5 kali lebih jauh (√6)', six: 'Sekitar 6 kali lebih jauh', 'thirty-six': 'Sekitar 36 kali lebih jauh' }, explanation: 'Jangkauan R = v² sin(2θ)/g berbanding terbalik dengan g. Karena gravitasi Bulan sekitar seperenam gravitasi Bumi, bola berada di udara enam kali lebih lama dan menempuh jarak enam kali lebih jauh (sekitar 6,06 kali untuk 9,81 dan 1,62 m/s²). Ketinggian maksimumnya juga enam kali lebih besar.' },
    train: { question: 'Seseorang di kereta yang bergerak dengan kecepatan horizontal bola mengamati lemparan tersebut. Lintasan apa yang terlihat?', task: 'Pilih “Seen from: a moving train”, tekan “Match the ball”, lalu luncurkan pada sudut antara 10° dan 80°.', options: { parabola: 'Parabola yang sama seperti dilihat dari tanah', vertical: 'Lurus ke atas lalu lurus ke bawah', line: 'Garis lurus miring', circle: 'Lingkaran' }, explanation: 'Bagi pengamat di kereta, bola tidak memiliki kecepatan horizontal (x′ = x − ut dengan u = v_x), sehingga bergerak lurus ke atas dan ke bawah. Bentuk lintasan bergantung pada pengamat, tetapi percepatan gravitasi tetap ke bawah dan hukum Newton berlaku bagi keduanya. Ini adalah relativitas Galilea.' },
    'drag-angle': { question: 'Dengan hambatan udara dan kecepatan bola bisbol minimal 30 m/s, apakah sudut 45° masih menghasilkan jangkauan terjauh?', task: 'Di Bumi, aktifkan hambatan udara, atur ketinggian 0 dan kecepatan minimal 30 m/s. Luncurkan pada 45° dan 40° lalu bandingkan jangkauannya.', options: { yes: 'Ya, 45° selalu paling baik', lower: 'Tidak: sudut terbaik lebih kecil dari 45°', higher: 'Tidak: sudut terbaik lebih besar dari 45°', 'no-effect': 'Hambatan udara tidak memengaruhi jangkauan' }, explanation: 'Hambatan udara mengurangi kecepatan bola selama penerbangan. Lintasan yang lebih datar dan singkat kehilangan lebih sedikit kecepatan, sehingga sudut terbaik turun di bawah 45°. Untuk model bola bisbol ini, sudutnya sekitar 42° pada 30 m/s dan 41° pada 40 m/s. Bentuk lintasannya juga tidak simetris; komputer menghitungnya dengan mengintegrasikan hukum Newton langkah demi langkah.' },
  },
  'moving-clocks': {
    dilation: { question: 'Pesawat ruang angkasa melintasi Bumi dengan kecepatan 0,80c. Kedua jam menunjukkan 0 s saat berpapasan. Menurut pengamat di Bumi, berapa bacaan jam pesawat ketika jam Bumi menunjukkan 10 s?', task: 'Pilih “Seen from: Earth”, atur kecepatan pesawat 0,80c, lalu jalankan jam hingga 10 s.', options: { same: '10 s: waktu sama di mana-mana', six: '6 s: jam yang bergerak berjalan lebih lambat', more: 'Sekitar 16,7 s: jam yang bergerak berjalan lebih cepat', zero: '0 s: jam yang bergerak berhenti' }, explanation: 'Pada 0,80c, faktor Lorentz γ = 1/√(1 − 0,80²) = 1,667. Jadi jam pesawat bertambah 10 s / 1,667 = 6,00 s ketika jam Bumi bertambah 10 s. Ini adalah dilatasi waktu, yang telah diukur melalui muon berkecepatan tinggi dan jam atom pada pesawat.' },
    'own-clock': { question: 'Sekarang lihat dari sudut pandang astronaut. Menurut astronaut, bagaimana jam pesawatnya sendiri berdetak?', task: 'Ubah “Seen from” menjadi ship, pertahankan kecepatan minimal 0,50c, dan jalankan jam setidaknya 3 detik.', options: { normal: 'Normal: satu detik setiap detik', slow: 'Lambat karena pesawat bergerak cepat', stopped: 'Berhenti', fast: 'Lebih cepat dari biasanya' }, explanation: 'Dalam kerangkanya sendiri, pesawat diam. Jamnya berdetak satu detik per detik, dan detak jantung serta proses biologis astronaut berjalan seiring. Tidak seorang pun merasakan waktunya sendiri melambat. Dilatasi waktu adalah perbandingan antara jam yang bergerak relatif satu sama lain.' },
    reciprocal: { question: 'Masih dalam kerangka pesawat: jam mana yang berjalan lebih lambat?', task: 'Pilih “Seen from: the ship”, pertahankan kecepatan minimal 0,50c, jalankan setidaknya 3 detik, lalu bandingkan kedua jam.', options: { earth: 'Jam Bumi: menurut pesawat, Bumilah yang bergerak', ship: 'Jam pesawat, sama seperti menurut Bumi', neither: 'Tidak ada: kedua jam sepakat dari pesawat', both: 'Kedua jam melambat' }, explanation: 'Dilatasi waktu bersifat simetris. Dalam kerangka pesawat, Bumi bergerak dengan kecepatan −β, sehingga jam Bumi berjalan lebih lambat dengan faktor γ yang sama. Kedua pengamat benar karena mereka tidak sepakat tentang peristiwa mana yang terjadi “sekarang”; garis keserempakan mereka berbeda.' },
    invariant: { question: 'Perhatikan satu peristiwa: “jam pesawat menunjukkan τ”. Kedua kerangka memberikan koordinat (t, x) yang berbeda. Besaran apa yang disepakati keduanya?', task: 'Jalankan pada kecepatan sama sekali dari setiap kerangka (minimal 3 s). Bandingkan t, x, dan s² = t² − x² pada tampilan.', options: { t: 'Koordinat waktunya t', x: 'Posisinya x', interval: 'Interval s² = t² − x² (dengan c = 1), yang sama dengan τ²', none: 'Tidak ada: semua koordinat bergantung pada kerangka' }, explanation: 'Koordinat t dan x berubah dalam transformasi Lorentz, tetapi interval s² = c²t² − x² tidak berubah. Pada garis dunia pesawat, interval ini sama dengan τ², sehingga waktu wajar merupakan sifat geometris lintasan yang sama bagi semua pengamat. Inilah gagasan utama ruang-waktu.' },
  },
  'two-perspectives': {
    headlight: { question: 'Pesawat ruang angkasa bergerak dengan kecepatan 0,50c dan menyalakan lampu depan yang mengarah ke depan. Berapa kecepatan cahaya menurut pengamat di Bumi?', task: 'Pilih skenario “Headlight”, atur kecepatan pesawat minimal 0,50c, lalu tekan “Make the measurement”.', options: { sum: '1,50c: kecepatan pesawat ditambahkan ke kecepatan cahaya', c: '1,00c: tepat sebesar kecepatan cahaya', half: '0,50c', 'bit-more': 'Sedikit lebih besar dari 1,00c' }, explanation: 'Setiap pengukuran menghasilkan c, berapa pun kecepatan sumbernya. Penjumlahan kecepatan Galilea memprediksi 1,50c dan gagal. Kedua deskripsi relativistik memprediksi c: dalam ruang dan waktu terpisah, kecepatan mengikuti aturan relativistik; dalam ruang-waktu, garis dunia cahaya memiliki interval nol.' },
    everyday: { question: 'Pada 0,01c (3.000 km/s, masih jauh lebih cepat daripada roket mana pun), seberapa besar perbedaan prediksi Galilea dan relativistik untuk jam bergerak?', task: 'Pilih “Moving clock”, atur kecepatan rendah seperti 0,01c (lebih besar dari 0 dan maksimal 0,05c), ukur, lalu bandingkan tiga prediksi.', options: { tiny: 'Sangat kecil: sekitar 0,005%', one: 'Sekitar 1%', ten: 'Sekitar 10%', total: 'Sangat berbeda sepenuhnya' }, explanation: 'Jam relativistik lebih lambat dengan fraksi 1 − 1/γ ≈ v²/2c², yaitu 0,00005 (0,005%) pada 0,01c dan jauh lebih kecil pada kecepatan sehari-hari. Itulah sebabnya fisika Newton sangat akurat dalam kehidupan sehari-hari: deskripsi Galilea adalah batas kecepatan rendah dari relativitas. Cahaya merupakan pengecualian.' },
    simultaneity: { question: 'Dua petir menyambar bersamaan menurut kerangka Bumi, dengan jarak 10 detik-cahaya. Pesawat melintas dengan kecepatan 0,60c menuju petir di depan. Menurut pesawat, petir mana yang menyambar lebih dahulu?', task: 'Pilih “Two flashes”, atur kecepatan minimal 0,30c, lalu lakukan pengukuran.', options: { same: 'Tidak ada: keduanya tetap serempak', front: 'Petir di depan (yang dituju pesawat)', rear: 'Petir di belakang', position: 'Bergantung pada posisi pesawat saat petir menyambar' }, explanation: 'Menurut pesawat, kilatan di depan terjadi lebih dahulu sebesar γvΔx/c², yaitu 7,5 s pada 0,60c. Keserempakan bersifat relatif. Ini bukan soal waktu cahaya mencapai pesawat, melainkan peristiwa jauh mana yang disebut serempak oleh jam-jam tersinkronisasi milik pesawat.' },
    equivalence: { question: 'Adakah pengukuran yang membuat deskripsi “ruang + waktu yang dihubungkan transformasi Lorentz” dan deskripsi “ruang-waktu” memberikan hasil berbeda?', task: 'Lakukan pengukuran pada ketiga skenario dengan kecepatan minimal 0,50c, lalu bandingkan dua kolom deskripsi tersebut.', options: { fast: 'Ya, pada kecepatan mendekati c', simultaneity: 'Ya, untuk keserempakan yang hanya dapat dijelaskan ruang-waktu', none: 'Tidak: keduanya adalah dua rumusan teori yang sama', dimension: 'Ya: ruang-waktu memprediksi dimensi keempat yang dapat dideteksi' }, explanation: 'Keduanya selalu sepakat: transformasi Lorentz adalah rotasi hiperbolik yang mempertahankan metrik ruang-waktu. Prediksi terukur dapat dihitung dari koordinat dalam kerangka pilihan atau dari besaran invarian, dan hasilnya sama. Perbedaannya terletak pada cara teori menyajikan dasar matematisnya, bukan pada prediksi fisiknya.' },
  },
  'gravity-clocks': {
    mountain: { question: 'Satu jam berada di permukaan laut dan jam identik lainnya di puncak Everest, 8,8 km lebih tinggi. Setelah beberapa waktu, jam mana yang mencatat waktu lebih banyak?', task: 'Pilih Bumi, letakkan jam A di permukaan laut dan jam B di Everest, lalu jalankan setidaknya satu hari.', options: { sea: 'Jam di permukaan laut', everest: 'Jam di puncak Everest', same: 'Tidak ada: keduanya tetap sinkron', depends: 'Bergantung pada siapa yang mengamati' }, explanation: 'Jam yang lebih dalam di medan gravitasi berjalan lebih lambat. Jam di Everest bertambah sekitar 83 nanodetik per hari dibandingkan jam di permukaan laut. Semua proses di sana berjalan dengan laju yang sama lebih cepat, termasuk detak jantung dan reaksi kimia. Perbedaannya terlihat ketika jam dibandingkan.' },
    gps: { question: 'Satelit GPS mengorbit pada ketinggian 20.200 km dengan kecepatan sekitar 3,9 km/s. Dibandingkan jam di permukaan Bumi, jam satelit…', task: 'Beralih ke “GPS satellite” dan jalankan jam setidaknya satu hari.', options: { fast: 'Berjalan lebih cepat sekitar 38 mikrodetik per hari', slow: 'Berjalan lebih lambat karena bergerak sangat cepat', same: 'Berdetak tepat dengan laju yang sama', second: 'Berjalan lebih cepat sekitar 1 detik per hari' }, explanation: 'Dua efek saling bersaing. Gravitasi yang lebih lemah membuat jam satelit bertambah sekitar 45,7 μs per hari. Kecepatan orbit membuatnya kehilangan sekitar 7,2 μs per hari akibat dilatasi waktu. Efek gravitasi menang, sehingga hasil bersihnya sekitar +38,5 μs per hari.' },
    uncorrected: { question: 'GPS menentukan posisi dari waktu tempuh sinyal. Jika insinyur mengabaikan relativitas, seberapa cepat posisi akan menyimpang?', task: 'Dalam mode “GPS satellite”, matikan koreksi relativitas dan jalankan setidaknya satu hari.', options: { metre: 'Sekitar 1 meter per hari', km: 'Sekitar 10 kilometer per hari', mm: 'Sekitar 1 milimeter per hari', none: 'Tidak sama sekali: efeknya terlalu kecil' }, explanation: 'Cahaya menempuh sekitar 300 m dalam satu mikrodetik. Kesalahan jam 38,5 μs per hari menjadi kesalahan pengukuran jarak sekitar 11,5 km per hari. Karena itu jam satelit dikalibrasi sebelum peluncuran agar lajunya tepat ketika berada di orbit.' },
    horizon: { question: 'Sebuah jam diturunkan perlahan mendekati horizon peristiwa lubang hitam. Dibandingkan jam yang jauh, apa yang terjadi pada lajunya saat semakin dekat?', task: 'Pilih lubang hitam, letakkan jam A pada jarak 0,01 r_s di atas horizon atau lebih dekat, lalu jalankan jam.', options: { zero: 'Mendekati nol', half: 'Turun menjadi setengah lalu tetap', backwards: 'Berjalan mundur', faster: 'Berjalan semakin cepat' }, explanation: 'Jam yang diam pada radius r berdetak dengan laju √(1 − r_s/r) dibandingkan jam jauh, dan faktor ini mendekati nol di horizon. Ini tidak berarti waktu berhenti bagi jam tersebut: jam yang jatuh bebas melintasi horizon dalam waktu wajarnya sendiri yang terbatas. “Waktu berhenti” adalah perbandingan dengan jam jauh.' },
    agree: { question: 'Dalam eksperimen “Jam berbeda”, setiap pengamat bergerak menganggap jam pengamat lain berjalan lambat. Di sini, apakah pengamat pada jam bawah dan atas sepakat jam mana yang lambat?', task: 'Jalankan dua jam pada ketinggian berbeda setidaknya satu hari, lalu bandingkan tampilan “signals received”.', options: { agree: 'Ya: keduanya menyimpulkan jam bawah lebih lambat', mutual: 'Tidak: masing-masing menganggap jam lain lebih lambat', unknowable: 'Tidak ada yang dapat mengetahuinya', frame: 'Bergantung pada kerangka acuan' }, explanation: 'Keduanya sepakat. Detak yang dikirim ke atas tiba lebih lambat (pergeseran merah), sedangkan detak ke bawah tiba lebih cepat (pergeseran biru), dengan faktor yang saling berbalikan. Pengamat atas melihat jam bawah lambat dan pengamat bawah melihat jam atas cepat. Situasinya tidak simetris karena satu jam berada lebih dalam di sumur gravitasi.' },
  },
  'evolving-space': {
    centre: { question: 'Astronom mengamati galaksi jauh bergerak menjauh dari kita ke segala arah. Di manakah pusat ekspansi?', task: 'Klik galaksi dekat tepi untuk menjadikannya “home”, lalu jalankan model setidaknya 2 miliar tahun. Amati panahnya.', options: { us: 'Galaksi kita sendiri', far: 'Titik khusus yang jauh di suatu tempat', none: 'Tidak ada pusat: setiap galaksi melihat galaksi lain menjauh', edge: 'Di tepi alam semesta' }, explanation: 'Dari galaksi mana pun yang ikut aliran kosmologis, pola skala besar tampak sama: galaksi lain yang tidak terikat memiliki jarak wajar yang bertambah. Faktor skala a(t) menggambarkan perubahan geometri ruang-waktu; ia bukan zat ruang yang membawa galaksi menjauh. Dentuman Besar bukan ledakan dari satu titik ke ruang kosong yang sudah ada.' },
    bound: { question: 'Ketika ruang mengembang, apakah galaksi itu sendiri (juga Bumi dan Anda) ikut mengembang?', task: 'Jalankan model maju atau mundur setidaknya 5 miliar tahun. Bandingkan ukuran galaksi dengan jarak di antaranya.', options: { all: 'Ya: segala sesuatu membesar bersama alam semesta', bound: 'Tidak: benda yang terikat gravitasi atau gaya lain mempertahankan ukurannya', galaxies: 'Galaksi membesar, tetapi planet tidak', shrink: 'Benda menyusut sementara jarak antarbenda membesar' }, explanation: 'Faktor skala FLRW menggambarkan perubahan jarak wajar antara objek yang ikut aliran kosmologis pada skala kosmologis. Benda terikat tidak ikut mengembang: galaksi terikat gravitasi dan atom oleh interaksi elektromagnetik. Bima Sakti, Tata Surya, dan manusia tidak membesar mengikuti faktor skala kosmik.' },
    faster: { question: 'Tidak ada benda yang dapat bergerak menembus ruang lebih cepat daripada cahaya. Dapatkah galaksi jauh menjauh dari kita dengan laju lebih besar daripada cahaya?', task: 'Dalam model alam semesta kita saat ini, tingkatkan jarak galaksi jauh hingga laju resesinya mencapai c.', options: { never: 'Tidak, tidak pernah', yes: 'Ya, jika cukup jauh, tanpa melanggar relativitas', past: 'Hanya pada masa lampau yang jauh', engines: 'Hanya jika galaksi itu sendiri bergerak cepat' }, explanation: 'Laju resesi FLRW v = H d dapat melebihi c di luar jarak Hubble c/H. Ini adalah laju perubahan jarak wajar antara pengamat yang terpisah jauh dan ikut aliran kosmologis, bukan kecepatan lokal saat satu galaksi melewati galaksi lain. Secara lokal, setiap pengamat tetap mengukur cahaya bergerak dengan laju c.' },
    age: { question: 'Perkiraan sederhana usia alam semesta adalah 1/H₀ ≈ 14,5 miliar tahun. Berapa hasil persamaan Friedmann jika materi dan energi gelap disertakan?', task: 'Pilih “Our universe” dan mundur ke Dentuman Besar. Baca waktu saat ini yang diukur sejak awal tersebut.', options: { same: 'Tepat 1/H₀: 14,5 miliar tahun', planck: 'Sekitar 13,8 miliar tahun', matter: 'Sekitar 9,6 miliar tahun (2/3 dari 1/H₀)', infinite: 'Usianya tak terhingga' }, explanation: 'Usia alam semesta adalah t₀ = ∫ da / (a H(a)) ≈ 13,8 miliar tahun. Materi memperlambat ekspansi pada masa lalu, sedangkan energi gelap mempercepatnya belakangan. Keduanya membuat hasil berbeda dari 1/H₀. Model yang hanya berisi materi menghasilkan usia sekitar 9,6 miliar tahun.' },
    acceleration: { question: 'Dalam alam semesta kita, kapan ekspansi berubah dari melambat menjadi semakin cepat?', task: 'Jalankan model alam semesta kita melewati bagian tengah sejarahnya dan amati indikator “Expansion is…” serta perlambatan q.', options: { always: 'Sejak awal selalu semakin cepat', six: 'Sekitar 6 miliar tahun lalu', never: 'Belum: ekspansi masih melambat', start: 'Tepat saat Dentuman Besar' }, explanation: 'Radiasi, materi, dan energi gelap menentukan peralihan tersebut. Dalam model ini q = 0 terjadi pada faktor skala sekitar 0,609, pergeseran merah z ≈ 0,642, atau sekitar 6,14 miliar tahun lalu. Percepatan ekspansi ditemukan pada 1998 melalui pengamatan supernova jauh.' },
  },
  'force-lab': {
    'held': { question: "Sebuah balok 5 kg diam di lantai datar. Anda mendorongnya ke samping dengan 10 N, tetapi balok tidak bergerak. Berapa besar gaya gesek padanya?", task: "Pada permukaan horizontal, pilih dorongan yang cukup kecil agar balok tetap diam, jalankan percobaan, lalu baca gaya geseknya.", options: {"zero": "Nol: tidak ada yang bergerak, jadi tidak ada gesekan", "equal": "10 N, tepat mengimbangi dorongan", "maximum": "Nilai maksimumnya, μsN", "larger": "Lebih dari 10 N, kalau tidak balok akan bergerak"}, explanation: "Balok tetap diam, sehingga gaya resultan padanya nol dan gaya gesek harus tepat meniadakan dorongan: 10 N. Gaya gesek statis bukan jumlah yang tetap. Nilainya menyesuaikan dengan yang diperlukan untuk mencegah balok bergeser, hingga maksimum μsN. Dorong lebih kuat dan gaya gesek ikut membesar, sampai batas itu tercapai." },
    'breakaway': { question: "Anda terus memperbesar dorongan sampai balok mulai bergeser. Setelah balok bergeser, gaya geseknya…", task: "Pertahankan balok dan permukaan yang sama. Jalankan satu percobaan saat balok tetap diam dan satu percobaan dengan dorongan yang cukup besar untuk membuatnya bergeser, lalu bandingkan gaya geseknya.", options: {"larger": "Lebih besar daripada gaya gesek statis terbesar", "smaller": "Lebih kecil: gesekan kinetis μkN lebih kecil daripada maksimum statis μsN", "same": "Sama persis dengan maksimum statis", "zero": "Nol, karena balok sudah terlepas"}, explanation: "Setelah balok bergeser, gaya gesek menjadi gesekan kinetis μkN, yang untuk sebagian besar permukaan lebih kecil daripada maksimum statis μsN. Karena itulah mendorong kotak berat agar mulai bergerak lebih sulit daripada menjaganya tetap bergerak. Gesekan kinetis tidak bertambah seiring dorongan: kelebihan dorongan kini menghasilkan percepatan." },
    'incline-normal': { question: "Sebuah balok diam di bidang miring 30°. Dibandingkan dengan beratnya mg, gaya normal dari permukaan adalah…", task: "Pilih bidang miring dengan sudut 15° atau lebih curam, jalankan percobaan, lalu bandingkan gaya normal dengan berat.", options: {"equal": "Sama dengan mg: permukaan selalu menopang seluruh berat", "cos": "Lebih kecil: mg cos θ", "sin": "Lebih kecil: mg sin θ", "larger": "Lebih besar daripada mg"}, explanation: "Permukaan mendorong tegak lurus terhadap dirinya, sehingga gaya normal hanya perlu meniadakan bagian berat yang mengarah ke dalam permukaan: N = mg cos θ (87 % dari berat pada 30°). Bagian lainnya, mg sin θ, mengarah ke bawah bidang. Karena gesekan maksimum adalah μsN, bidang yang lebih curam juga menurunkan batas gesekan." },
    'mass-independence': { question: "Tanpa dorongan, balok ringan dan balok berat dari bahan yang sama diam di bidang miring yang sama. Saat kemiringan dinaikkan, balok mana yang mulai bergeser lebih dulu?", task: "Pada bidang miring dengan dorongan 0 N, jalankan sudut dan koefisien gesek yang sama dengan dua massa berbeda. Coba sudut di kedua sisi titik saat balok mulai bergeser.", options: {"heavy": "Balok berat: beratnya menarik lebih kuat ke bawah bidang", "light": "Balok ringan: gesekan yang menahannya lebih kecil", "same": "Keduanya pada sudut yang sama, saat tan θ = μs", "never": "Tidak ada: gesekan selalu menahan balok yang diam"}, explanation: "Tarikan ke bawah bidang, mg sin θ, dan batas gesekan, μs mg cos θ, sama-sama sebanding dengan massa, sehingga massa saling menghapus: balok mulai bergeser saat tan θ > μs, berapa pun massanya (sekitar 21,8° untuk μs = 0,40). Setelah bergeser, a = g(sin θ − μk cos θ) juga tidak bergantung pada massa. Mengukur sudut saat balok mulai bergeser adalah cara baku untuk mengukur μs." },
  },
  'length-contraction': {
    'moving': { question: "Sebuah pesawat ruang angkasa sepanjang 10 m melintasi Bumi dengan kecepatan 0,8c. Pengamat di Bumi mencatat posisi ujung depan dan belakangnya pada waktu Bumi yang sama. Berapa panjang yang mereka ukur?", task: "Atur kecepatan 0,5c atau lebih, lalu jalankan pengukuran. Bandingkan panjang terukur L dengan panjang wajar L₀.", options: {"same": "Tetap 10 m", "shorter": "Lebih pendek dari 10 m", "longer": "Lebih panjang dari 10 m", "zero": "Nol: terlalu cepat untuk diukur"}, explanation: "Pengamat di Bumi mengukur L = L₀/γ: pada 0,8c, γ = 1,667 dan pesawat 10 m terukur 6 m. Tidak ada yang menekan pesawat. Dalam kerangka diamnya sendiri, panjangnya tetap 10 m, yaitu panjang wajarnya. Kedua kerangka tidak sepakat tentang pasangan peristiwa ujung mana yang terjadi “pada saat yang sama”, sehingga mereka tidak sepakat tentang panjangnya." },
    'rest': { question: "Pesawat yang sama kini diparkir di dekat Bumi, diam relatif terhadap pengamat Bumi. Berapa panjang yang mereka ukur sekarang?", task: "Atur kecepatan relatif menjadi 0, lalu jalankan pengukuran.", options: {"proper": "Panjang wajarnya, 10 m", "shorter": "Masih sedikit lebih pendek dari 10 m", "longer": "Lebih panjang dari 10 m"}, explanation: "Tanpa gerak relatif, Bumi dan pesawat berada dalam satu kerangka dan sepakat tentang arti “pada saat yang sama”, sehingga Bumi mengukur panjang wajarnya, 10 m. Kontraksi panjang bukan perubahan permanen pada pesawat. Efek ini hanya bergantung pada kecepatan relatif antara benda dan pengukurnya." },
    'doubling': { question: "Kecepatan pesawat menjadi dua kali, dari 0,4c ke 0,8c. Bagaimana perubahan besar pemendekannya, L₀ − L?", task: "Pertahankan panjang wajar. Ukur pada 0,40c dan 0,80c, lalu bandingkan selisih panjang di tabel.", options: {"double": "Menjadi dua kali, seperti kecepatannya", "five": "Bertambah hampir lima kali", "same": "Tetap sama", "half": "Menjadi setengahnya"}, explanation: "L = L₀√(1 − v²/c²) jauh dari linear terhadap v. Pada 0,4c, pesawat 10 m memendek 0,83 m; pada 0,8c memendek 4 m, hampir lima kali lipat. Pada kecepatan rendah, L₀ − L ≈ L₀v²/(2c²) bertambah sebanding dengan kuadrat kecepatan, dan mendekati c pemendekan bertambah lebih cepat lagi. Itulah sebabnya efek ini tidak terasa pada kecepatan sehari-hari." },
    'simultaneity': { question: "Bumi mencatat ujung belakang dan depan pada waktu Bumi yang sama. Dalam kerangka pesawat, apakah kedua peristiwa pencatatan itu serentak?", task: "Jalankan pengukuran pada kecepatan bukan nol mana pun, lalu baca selisih waktu peristiwa ujung dalam kerangka pesawat.", options: {"yes": "Ya: peristiwa serentak bersifat serentak bagi semua pengamat", "front": "Tidak: ujung depan dicatat lebih dulu, selisih vL₀/c²", "rear": "Tidak: ujung belakang dicatat lebih dulu, selisih vL₀/c²"}, explanation: "Transformasi Lorentz memberi Δt′ = γ(Δt − vΔx/c²) = −vL₀/c² untuk Δt = 0: dalam kerangka pesawat, ujung depan dicatat lebih dulu. Dari sudut pandang pesawat, Bumi tidak menandai kedua ujung pada saat yang sama, sehingga hasil Bumi bukan panjang dalam kerangka pesawat dan tidak harus sama dengan L₀. Kontraksi panjang adalah relativitas keserempakan yang diterapkan pada kedua ujung sebuah benda." },
  },
  'momentum-collisions': {
    'swap': { question: "Kereta 1 meluncur dengan 4 m/s menuju kereta 2 yang identik dan diam. Tumbukannya lenting sempurna (e = 1). Apa yang terjadi kemudian?", task: "Beri kedua kereta massa yang sama, kecepatan kereta 2 nol, dan kecepatan kereta 1 positif. Atur e = 1, jalankan tumbukan, lalu baca kecepatan akhirnya.", options: {"swap": "Kereta 1 berhenti dan kereta 2 bergerak dengan 4 m/s", "share": "Kedua kereta bergerak bersama dengan 2 m/s", "bounce": "Kereta 1 memantul balik dengan 4 m/s", "both-move": "Kedua kereta bergerak maju, kereta 2 sedikit lebih cepat"}, explanation: "Momentum harus tetap 8 kg·m/s, dan dalam tumbukan lenting sempurna energi kinetik juga harus tetap. Dengan massa yang sama, satu-satunya cara menjaga keduanya adalah kedua kereta bertukar kecepatan: kereta 1 berhenti dan kereta 2 melaju dengan 4 m/s. Anda mungkin pernah melihat hal yang sama pada bola biliar atau ayunan Newton." },
    'stick': { question: "Dua kereta yang sama kini saling menempel saat bertumbukan (e = 0). Seberapa cepat keduanya bergerak setelahnya?", task: "Pertahankan massa yang sama dengan kereta 2 diam, atur e = 0, lalu jalankan tumbukan.", options: {"same": "Dengan kelajuan awal kereta 1", "half": "Dengan setengah kelajuan awal kereta 1", "stop": "Keduanya berhenti", "quarter": "Dengan seperempat kelajuan awal kereta 1"}, explanation: "Momentum tetap kekal: m·u = 2m·v, sehingga pasangan kereta bergerak dengan setengah kelajuan kereta 1. Energi kinetik tidak kekal di sini. Setengahnya berubah menjadi panas, bunyi, dan deformasi kereta. Kekekalan momentum menentukan kelajuan akhir, tetapi tidak menentukan berapa energi yang tersisa setelah tumbukan." },
    'conserved': { question: "Dalam tumbukan dengan e = 0,5, besaran mana yang sama sebelum dan sesudah tumbukan?", task: "Pilih koefisien restitusi antara 0 dan 1, jalankan tumbukan, lalu bandingkan momentum dan energi kinetik sebelum dan sesudahnya.", options: {"momentum": "Hanya momentum total", "energy": "Hanya energi kinetik total", "both": "Momentum dan energi kinetik", "neither": "Tidak keduanya"}, explanation: "Selama tumbukan, kedua kereta saling mendorong dengan gaya yang sama besar dan berlawanan arah selama waktu yang sama, sehingga impuls keduanya saling menghapus dan momentum total tidak berubah, berapa pun nilai e. Energi kinetik hanya kekal jika e = 1. Untuk 0 < e < 1, sebagian berubah menjadi energi dalam, dan kehilangannya adalah ΔK = ½μ(1 − e²)(u₁ − u₂)²." },
    'heavy-light': { question: "Kereta 10 kg yang bergerak dengan 4 m/s menumbuk kereta 1 kg yang diam secara lenting sempurna. Kelajuan kereta ringan setelahnya paling dekat dengan…", task: "Buat kereta 1 setidaknya lima kali lebih berat daripada kereta 2, buat kereta 2 diam, atur e = 1, lalu jalankan tumbukan.", options: {"same": "4 m/s, sama dengan kelajuan kereta berat", "double": "7,3 m/s, hampir dua kali kelajuan kereta berat", "small": "0,4 m/s", "forty": "40 m/s, membawa seluruh momentum"}, explanation: "Dalam kerangka pusat massa, tumbukan lenting sempurna hanya membalik setiap kecepatan. Pusat massa bergerak dengan 40/11 ≈ 3,6 m/s, sehingga kereta ringan mendekatinya dengan −3,6 m/s dan meninggalkannya dengan +3,6 m/s relatif terhadapnya: 7,3 m/s dalam kerangka laboratorium, v₂ = 2m₁u₁/(m₁ + m₂). Saat m₁/m₂ makin besar, kelajuan kereta ringan mendekati dua kali kelajuan kereta berat. Wahana antariksa memakai gagasan yang sama dalam manuver ketapel gravitasi di sekitar planet." },
  },
  'circular-orbits': {
    'direction': { question: "Sebuah satelit mengelilingi Bumi dalam lingkaran dengan kelajuan tetap. Ke mana arah gaya resultan padanya?", task: "Atur kelajuan peluncuran tepat 1,00 × kelajuan orbit lingkaran, luncurkan, lalu perhatikan panah gaya pada satelit.", options: {"centre": "Menuju pusat lingkaran", "forward": "Ke depan, searah geraknya", "outward": "Ke luar, menjauhi pusat", "none": "Tidak ada gaya resultan: kelajuannya tetap"}, explanation: "Kelajuannya tetap, tetapi arah geraknya terus berbelok, sehingga kecepatannya berubah dan satelit mengalami percepatan. Percepatan itu, v²/r, mengarah ke pusat, dan demikian pula gaya resultannya: m v²/r. Bagi satelit, gaya itu adalah gravitasi. Tidak ada yang mendorongnya ke depan; satelit terus bergerak karena tidak ada yang menghentikannya." },
    'faster': { question: "Sekarang luncurkan satelit dari tempat yang sama, sedikit lebih cepat daripada kelajuan orbit lingkaran. Lintasan apa yang diikutinya?", task: "Luncurkan pada 1,05 sampai 1,35 × kelajuan orbit lingkaran, lalu bandingkan lintasannya dengan lingkaran.", options: {"ellipse": "Elips yang melebar lebih jauh di sisi seberang, lalu kembali ke titik peluncuran", "bigger": "Lingkaran yang lebih besar", "escape": "Satelit terbang lepas ke luar angkasa", "spiral": "Spiral yang terus melebar"}, explanation: "Gravitasi tidak lagi mampu membelokkan lintasan yang lebih cepat menjadi lingkaran, sehingga satelit naik. Sambil naik, satelit melambat, gravitasi kembali unggul, dan satelit jatuh kembali ke titik peluncuran, yang kini menjadi titik terdekat elips. Jika diluncurkan lebih lambat daripada kelajuan orbit lingkaran, titik peluncuran justru menjadi titik terjauh. Dalam kedua kasus orbit menutup dan berulang persis: dalam gravitasi Newton, orbit terikat adalah elips tertutup." },
    'kepler': { question: "Anda memindahkan orbit lingkaran dari 2 jari-jari Bumi ke 4 jari-jari Bumi. Periodenya…", task: "Jalankan dua orbit lingkaran (1,00 × kelajuan orbit lingkaran) yang jari-jarinya berbeda setidaknya 1,5 kali, lalu bandingkan periodenya.", options: {"cube": "Bertambah sekitar 2,8 kali", "double": "Menjadi dua kali", "same": "Tetap sama", "half": "Menjadi setengah, karena gravitasi lebih lemah"}, explanation: "Lintasannya dua kali lebih panjang, dan kelajuan orbit lingkaran √(GM/r) lebih kecil √2 kali, sehingga periode T = 2πr/v bertambah 2 × √2 ≈ 2,8 kali. Secara umum T² ∝ r³: hukum ketiga Kepler, yang ditemukan Kepler dari data planet dan dijelaskan Newton dengan gravitasi dan gerak melingkar." },
    'escape': { question: "Seberapa cepat satelit harus diluncurkan, dibandingkan dengan kelajuan orbit lingkaran pada ketinggian itu, agar tidak pernah kembali?", task: "Temukan ambangnya: jalankan satu orbit pada 1,2 × kelajuan orbit lingkaran atau lebih yang masih kembali, dan satu peluncuran yang lepas.", options: {"root2": "√2 ≈ 1,41 kali kelajuan orbit lingkaran", "two": "Dua kali kelajuan orbit lingkaran", "any": "Kelajuan berapa pun di atas kelajuan orbit lingkaran", "never": "Satelit selalu kembali pada akhirnya"}, explanation: "Satelit lepas jika energi kinetiknya cukup untuk keluar dari sumur gravitasi: ½v² − GM/r ≥ 0, sehingga v ≥ √(2GM/r) = √2 · v_c. Tepat pada √2 lintasannya parabola; lebih cepat lagi, hiperbola. Kelajuan lepas hanya bergantung pada titik awal, bukan pada arah (asalkan lintasannya tidak menabrak planet)." },
  },
  'geodesic-motion': {
    'perturbed': { question: "Sebuah wahana mengorbit lubang hitam pada 8 rₛ, tetapi momentum sudutnya sedikit lebih kecil daripada yang diperlukan untuk orbit lingkaran. Seperti apa lintasannya setelah beberapa kali mengorbit?", task: "Mulai pada 8 rₛ atau lebih dengan momentum sudut sedikit berbeda dari 1 × L lingkaran, jalankan eksperimen, lalu bandingkan kedua lintasan.", options: {"circle": "Lingkaran", "ellipse": "Elips tertutup yang sama, dilalui berulang-ulang", "precess": "Elips yang titik terdekatnya bergeser sedikit setiap orbit", "spiral": "Spiral yang jatuh ke lubang hitam"}, explanation: "Dalam gravitasi Newton, orbitnya berupa elips tertutup yang berulang persis (lintasan putus-putus). Dalam ruang-waktu Schwarzschild, titik terdekat, yaitu periapsis, maju setiap orbit sehingga lintasannya membentuk roset. Orbit Merkurius mengelilingi Matahari juga demikian, meskipun sangat lambat; menjelaskannya merupakan salah satu keberhasilan pertama relativitas umum." },
    'circular': { question: "Sekarang beri wahana momentum sudut yang tepat sama dengan orbit lingkaran, tanpa kecepatan ke dalam atau ke luar. Lintasan apa yang diikutinya?", task: "Atur momentum sudut menjadi 1,000 × L lingkaran dan kecepatan radial menjadi 0, lalu jalankan eksperimen.", options: {"circle": "Lingkaran", "precess": "Elips yang berputar perlahan", "spiral": "Spiral yang jatuh ke lubang hitam"}, explanation: "Orbit lingkaran tetap ada dalam ruang-waktu Schwarzschild: dengan momentum sudut yang tepat dan tanpa gerak radial, jari-jari tidak pernah berubah, sehingga tidak ada periapsis yang bergeser. Presesi hanya muncul jika orbit tidak lingkaran sempurna. Di bawah 3 rₛ, bahkan orbit lingkaran menjadi tidak stabil, dan dorongan sekecil apa pun membuat wahana jatuh ke dalam." },
    'distance': { question: "Anda memindahkan orbit yang sedikit lonjong menjauhi lubang hitam, dari 5 rₛ ke 12 rₛ. Pergeseran periapsis per orbit…", task: "Pertahankan momentum sudut dan kecepatan radial yang sama, lalu ukur pergeseran per orbit pada dua jari-jari awal yang berselisih setidaknya 3 rₛ.", options: {"grows": "Bertambah", "shrinks": "Berkurang", "same": "Tetap sama", "reverses": "Berbalik arah"}, explanation: "Suku relativistik −3L²/(2r⁴) dalam persamaan radial berkurang lebih cepat daripada suku Newton −1/(2r²), sehingga makin jauh orbitnya, makin mirip elips Newton yang tertutup. Untuk orbit yang hampir lingkaran, pergeserannya sekitar 360°·(1/√(1 − 3rₛ/r) − 1): kira-kira 210° per orbit pada 5 rₛ tetapi 56° pada 12 rₛ. Inilah limit Newtonian." },
    'mercury': { question: "Jauh dari massa, pergeseran per orbit sekitar 3π rₛ/r radian. Merkurius mengorbit sekitar 2 × 10⁷ rₛ dari Matahari. Pergeseran periapsisnya per orbit kira-kira…", task: "Periksa dulu perkiraan medan lemah: jalankan orbit yang hampir lingkaran (momentum sudut dalam rentang 0,01 dari 1, tanpa kecepatan radial) pada 10 rₛ atau lebih, lalu bandingkan pergeseran terukur dengan perkiraannya.", options: {"arcsec": "Sekitar 0,1 detik busur", "degree": "Sekitar 1 derajat", "radian": "Sekitar 0,5 radian", "zero": "Tepat nol: gravitasi Matahari terlalu lemah untuk relativitas"}, explanation: "3π/(2 × 10⁷) ≈ 5 × 10⁻⁷ rad ≈ 0,1″ per orbit. Dalam satu abad Merkurius menyelesaikan sekitar 415 orbit, sehingga totalnya 43″ per abad: anomali yang tidak dapat dijelaskan gravitasi Newton dan dihitung Einstein pada 1915. Rumus yang sama memberi sekitar 45° pada 12 rₛ; di sana hasil eksak untuk orbit hampir lingkaran, sekitar 56°, sudah jelas lebih besar." },
  },
}

const ja: LocalizedCatalogues['ja'] = {
  'space-vs-time': {
    rest: { question: '速度をゼロにして時計を動かします。位置–時間グラフはどうなりますか？', task: 'v = 0 に設定し、時計を少なくとも3秒間動かします。', options: { flat: '水平線：時間は進み続けるが位置は変わらない', dot: '一点：何も変化しないので時間も止まる', vertical: '垂直線', rising: '右上がりの線' }, explanation: '物体は動いていませんが、時計は進み続けます。グラフは右（時間）へ伸びますが、上下（位置）には変化しません。空間内の運動を止めても時計は止まりません。x(t) = x₀ + v·t で v = 0 とすれば、すべての t について x = x₀ です。' },
    double: { question: '同じ実験を2回行い、2回目は速度を2倍にします。グラフの線はどうなりますか？', task: '例えば1 m/sと2 m/sでそれぞれ3秒以上、速度を一定にして実験します。', options: { steeper: '傾きが2倍になる', shifted: '傾きは同じまま上に移動する', same: '見た目は同じで、終わるのが早くなるだけ', shallower: '傾きが半分になる' }, explanation: '位置–時間グラフの傾きは速度です：傾き = Δx / Δt = v。vを2倍にすると毎秒進む距離も2倍になり、線は2倍の速さで上昇します。x₀を変えた場合は傾きを変えずに線が上下へ移動します。' },
    reverse: { question: '1回の実験でx₀ = 0から+2 m/sで3秒進み、時計を止めずに速度を−2 m/sへ変えてさらに3秒進みます。変位Δxと移動距離はいくらですか？', task: '+2 m/sで開始します。約3秒後、時計を動かしたまま速度スライダーを−2 m/sにして、さらに3秒動かします。途中でリセットしないでください。', options: { 'zero-twelve': 'Δx = 0 m、距離 = 12 m', 'both-twelve': 'Δx = 12 m、距離 = 12 m', 'both-zero': 'Δx = 0 m、距離 = 0 m', 'twelve-zero': 'Δx = 12 m、距離 = 0 m' }, explanation: '変位は始点と終点だけを比べます：Δx = ∫v dt なので、前進と後退が打ち消し合います。距離は経路の長さs = ∫|v| dtであり、減少しません。向きを変えない運動でのみ両者は一致します。' },
    'moving-observer': { question: '物体はレール上で静止しています（v = 0）。別の観測者がu = +2 m/sで移動します。観測者自身の座標x′では、位置–時間グラフはどう見えますか？', task: 'リセットし、初期位置x₀ = +6 m、v = 0、観測者速度u = +2 m/sに設定します。時計を3秒以上動かし、オレンジ色の破線を見ます。', options: { flat: '水平線：物体は静止しているので誰にとっても静止している', down: '傾き−2 m/sの右下がりの線', up: '傾き+2 m/sの右上がりの線', undefined: '線はない：移動する観測者は物体の位置を定義できない' }, explanation: '観測者は各事象をx′ = x − u·tで表します。x = x₀は一定なので、x′ = x₀ − u·tとなり、傾きv′ = v − u = −u（u = +2 m/sなら−2 m/s）の直線です。観測者には物体が後方へ動いて見えます。どちらの記述も正しく、「静止」は基準系に対して相対的です。' },
  },
  displacement3d: {
    'round-trip': { question: 'ドローンが東へ3 m、北へ4 m、上へ2 m飛び、その後離陸地点へまっすぐ戻ります。変位はいくらですか？（東=+x、北=+y、上=+z）', task: '3回以上移動して出発点に戻るか、「Round trip」を読み込み、変位を確認します。', options: { zero: 'ゼロ', nine: '9 m', eighteen: '約14.4 m（飛行全体）', five: '5.4 m' }, explanation: '変位は終点と始点だけを比べます。ドローンは元の場所に戻るので変位はゼロです。移動距離はゼロではなく、往路3 + 4 + 2 mと復路√29 ≈ 5.4 mを合わせて約14.4 mです。距離は経路の長さ、変位は始点から終点への直線矢印です。' },
    diagonal: { question: 'x方向へ3 m、y方向へ4 m、z方向へ12 m移動します。始点から終点までの直線距離はいくらですか？', task: 'その移動を行うか「3, 4, 12 diagonal」を読み込み、変位の大きさを確認します。', options: { nineteen: '19 m', thirteen: '13 m', twelve: '12 m', seventeen: '約17 m' }, explanation: '三次元でもピタゴラスの定理が成り立ちます：|Δr| = √(3² + 4² + 12²) = 13 m。まず床面で√(3² + 4²) = 5 m、次に高さを加えて√(5² + 12²) = 13 mです。19 mは経路に沿った移動距離です。' },
    shift: { question: '座標系の原点を別の場所へ移すと、物体の変位はどうなりますか？', task: '移動を行い、第2座標系の原点を動かして2組の数値を比較します。', options: { unchanged: 'まったく変わらない', shifted: '原点の移動量だけ変わる', zero: 'ゼロになる', grows: '長くなる' }, explanation: '原点を移すとすべての位置が同じ量だけ変化します。しかし変位は2つの位置の差なので、その移動は相殺されます：Δr′ = (r_end − O) − (r_start − O) = Δr。原点の場所は選択ですが、物体がどれだけどちらへ動いたかは変わりません。' },
    rotation: { question: '座標軸を30°回転させます。どの量が変わらずに残りますか？', task: '移動を行い、第2座標系の軸を回転させて2組の数値を比較します。', options: { x: '変位のx成分', length: '変位の長さ |Δr|', all: '3つすべての成分', none: '何もない：すべて変わる' }, explanation: '軸を回転すると成分Δx′、Δy′、Δz′は変わりますが、幾何学的な矢印自体は変わらないため長さは同じです。すべての座標系で一致する量を不変量と呼びます。「異なる時計」と「空間と時間と時空」では時空間隔が同じ役割を果たします。' },
    triangle: { question: '移動距離が変位の大きさより短くなることはありますか？', task: '一直線上にない2回以上の移動を行い、距離と|Δr|を比較します。', options: { shortcut: '近道をすれば、はい', never: 'いいえ：直線が最短経路です', curved: '曲線経路の場合だけ', 'three-d': '三次元の場合だけ' }, explanation: '三角不等式 |Δr₁ + Δr₂| ≤ |Δr₁| + |Δr₂| は、ユークリッド空間で2点間の直線が最短経路であることを示します。したがって距離は変位以上で、直線移動のときだけ等しくなります。時空では逆に、2事象間の直線世界線が最大の固有時間を与えます。' },
  },
  pendulum: {
    length: { question: '振り子の糸を4倍の長さにします。1往復にかかる時間（周期）はどうなりますか？', task: '振れ角を20°以下にして、ある長さで周期を測り、長さを4倍（例：0.5 mから2.0 m）にして再測定します。', options: { same: '変わらない', double: '2倍になる', four: '4倍になる', half: '半分になる' }, explanation: '小さな振れでは周期T = 2π√(L/g)です。長さを4倍にすると周期は√4 = 2倍になります。そのため振り子時計は長い振り子を使います。' },
    mass: { question: '同じ糸のまま、おもりを10倍重いものに交換します。周期はどうなりますか？', task: '長さと振れ角を同じにして、軽いおもりと少なくとも5倍重いおもりで周期を測ります。', options: { shorter: '重いおもりは速く落ちるので短くなる', same: '変わらない', longer: '重いおもりは動かしにくいので長くなる', stops: '重いおもりはほとんど振れない' }, explanation: '重いおもりは重力に強く引かれますが、加速しにくさも同じ割合で増えるため、質量は相殺されます。これは重力質量と慣性質量の等価性に関係し、一般相対性理論の等価原理の出発点です。' },
    moon: { question: '地球で正確に時を刻む振り子時計を、重力が地球の約1/6の月へ持っていきます。時計はどうなりますか？', task: '同じ振り子（同じ長さ）の周期を地球と月で測り、2つの時計を比較します。', options: { slow: '約2.5倍遅くなる', six: '6倍遅くなる', same: '正確なまま', fast: '速くなる' }, explanation: 'T = 2π√(L/g)は1/√gに比例します。月の重力は地球の約1/6なので、1回の振れに約√6 ≈ 2.46倍の時間がかかります。これは時間そのものが遅くなるという意味ではなく、振り子の周期が重力に依存するためです。' },
    'time-itself': { question: 'では、月では時間そのものがよりゆっくり進むのでしょうか？', task: '同じ振り子を地球と月で測り、振り子時計と原子時計を比較します。', options: { yes: 'はい：振り子時計が遅いことが証拠です', no: 'いいえ：振り子は重力に依存し、月の原子時計はわずかに速く進みます', unknown: '知る方法はありません', pendulums: '振り子だけです：時計の種類ごとに時間が異なります' }, explanation: '振り子は時間だけでなく重力も測ります。周期はgに依存します。秒を定義する原子時計はそのようには動作しません。原子時計を比較すると、月の弱い重力のため月の時計は1日あたり約56マイクロ秒速く進みます。' },
    amplitude: { question: 'ガリレオは振り子の周期が振れ幅に依存しないと考えました。5°ではなく90°から放した場合、周期はどうなりますか？', task: '同じ振り子を90°以上と10°以下の角度から放して測定します。', options: { same: '同じ', longer: '約18%長くなる', shorter: '約18%短くなる', double: '約2倍になる' }, explanation: '復元力はθではなくsin θに比例するため、大きな振れはよりゆっくりになります。初期角90°では周期は小角近似の約1.180倍です。時計職人は振れを小さく一定に保ちます。' },
  },
  newtonian: {
    mass: { question: '同じ合力で2台の台車を押します。一方の質量は2倍です。加速度はどうなりますか？', task: '同じ力で質量を変えて2回モデルを実行し、測定された加速度を比較します。', options: { same: '両方とも同じ加速度になる', half: '重い台車の加速度は半分になる', double: '重い台車の加速度は2倍になる' }, explanation: 'ニュートンの第2法則はa = F_net/mです。同じ合力なら質量を2倍にすると加速度は半分になります。質量は運動の変化に対する抵抗を表します。' },
    force: { question: '同じ台車に働く合力を2倍にすると、加速度はどうなりますか？', task: '質量を一定に保ち、異なる2つの合力でモデルを実行して加速度を比較します。', options: { same: '変わらない', half: '半分になる', double: '2倍になる' }, explanation: '質量が一定なら、加速度は合力に比例します。合力を2倍にすると加速度も2倍になります。' },
  },
  projectile: {
    'best-angle': { question: '空気抵抗がない場合、水平な地面に最も遠く届く投射角はどれですか？', task: '高さを0にし、空気抵抗をオフにして、同じ速さで45°、それより小さい角度、大きい角度から発射します。', options: { '30': '30°', '45': '45°', '60': '60°', '90': '真上（90°）' }, explanation: '射程R = v² sin(2θ)/gは2θ = 90°、つまりθ = 45°で最大になります。低い角度は水平速度が大きい一方、飛行時間が短くなります。高い角度はその逆です。45°を挟んで等しい角度（30°と60°など）は同じ射程になります。' },
    drop: { question: '壁からボールを水平に投げるのと同時に、同じ高さから同じボールを落とします。どちらが先に地面に着きますか？', task: '角度0°、高さ5 m以上、空気抵抗オフに設定し、「Also drop a ball」にチェックして発射します。', options: { thrown: '投げたボール', dropped: '落としたボール', together: '同時に着地する', depends: '投げる強さによる' }, explanation: '水平方向と鉛直方向の運動は独立しています。両方とも鉛直初速度はゼロで、同じ重力を受けるため常に同じ高さにあります。投げたボールは横へ進むだけです。' },
    moon: { question: '宇宙飛行士が重力が地球の約1/6の月で同じ投射をします。ボールはどれだけ遠くまで飛びますか？', task: '空気抵抗なし、高さ0で、地球と月の両方で同じ速さ・角度の投射を行います。', options: { same: '同じ距離', root: '約2.5倍（√6）', six: '約6倍', 'thirty-six': '約36倍' }, explanation: '射程R = v² sin(2θ)/gはgに反比例します。月の重力は地球の約1/6なので、飛行時間も射程も約6倍になります（9.81と1.62 m/s²なら約6.06倍）。最高到達高度も6倍です。' },
    train: { question: 'ボールの水平速度と同じ速さで並走する列車の乗客には、ボールの軌道はどう見えますか？', task: '「Seen from: a moving train」を選び、「Match the ball」を押して、10°から80°の角度で発射します。', options: { parabola: '地上から見たものと同じ放物線', vertical: '真上に進み、真下に戻る', line: '傾いた直線', circle: '円' }, explanation: '列車から見るとボールの水平速度はゼロ（x′ = x − ut、u = v_x）なので、真上に上がって真下に戻ります。軌道の形は観測者によって変わりますが、下向きの重力加速度とニュートンの法則はどちらの観測者にも同じです。' },
    'drag-angle': { question: '空気抵抗がある場合、30 m/s以上の速い野球ボールでも45°が最長射程の角度ですか？', task: '地球で空気抵抗をオンにし、高さ0、速度30 m/s以上で45°と40°を比較します。', options: { yes: 'はい、常に45°が最適', lower: 'いいえ、最適角度は45°より小さい', higher: 'いいえ、最適角度は45°より大きい', 'no-effect': '空気抵抗は射程に影響しない' }, explanation: '空気抵抗は飛行中ずっとボールの速さを奪います。低く短い軌道では失う速さが少ないため、最適角度は45°より小さくなります。このモデルでは30 m/sで約42°、40 m/sで約41°です。軌道も非対称になり、コンピューターはニュートンの法則を数値積分して求めます。' },
  },
  'moving-clocks': {
    dilation: { question: '宇宙船が地球を0.80cで通過します。すれ違う瞬間、両方の時計は0秒です。地球の時計が10秒を示すとき、地球から見た宇宙船の時計は何秒ですか？', task: '「Seen from: Earth」を選び、宇宙船の速度を0.80cにして、時計を10秒まで動かします。', options: { same: '10秒：時間はどこでも同じ', six: '6秒：動く時計は遅れる', more: '約16.7秒：動く時計は速く進む', zero: '0秒：動く時計は止まる' }, explanation: '0.80cではローレンツ因子γ = 1/√(1 − 0.80²) = 1.667です。地球の時計が10秒進む間に宇宙船の時計は10/1.667 = 6.00秒進みます。これが時間の遅れであり、高速ミューオンや航空機に搭載した原子時計でも測定されています。' },
    'own-clock': { question: '宇宙飛行士自身の視点では、自分の宇宙船の時計はどのように進みますか？', task: '「Seen from」をshipに切り替え、速度を0.50c以上に保ち、時計を3秒以上動かします。', options: { normal: '通常どおり：1秒につき1秒', slow: '宇宙船が速く動くので遅い', stopped: '止まる', fast: '通常より速い' }, explanation: '宇宙船自身の基準系では船は静止しており、時計は1秒ごとに1秒進みます。心拍や思考、加齢も時計とともに進みます。自分自身の時間が遅くなると感じる人はいません。時間の遅れは相対運動する時計同士の比較です。' },
    reciprocal: { question: '宇宙船の基準系で考えます。どちらの時計が遅れますか？', task: '「Seen from: the ship」を選び、速度を0.50c以上にして3秒以上動かし、2つの時計を比較します。', options: { earth: '地球の時計：宇宙船からは地球が動いて見える', ship: '宇宙船の時計：地球から見た場合と同じ', neither: 'どちらも遅れない：宇宙船からは一致する', both: '両方の時計が遅れる' }, explanation: '時間の遅れは対称です。宇宙船の基準系では地球が−βで動くため、地球の時計が同じローレンツ因子γだけ遅れます。両者が正しいのは「今」とする事象が異なるためです。同時刻線が傾くことで、互いの時計を異なる読みで比較します。' },
    invariant: { question: '「宇宙船の時計がτを示す」という一つの事象を考えます。2つの基準系では座標(t, x)が異なります。両方が一致する量はどれですか？', task: '同じ速度で各基準系から3秒以上ずつ実験し、表示されたt、x、s² = t² − x²を比較します。', options: { t: '時間座標t', x: '位置x', interval: '間隔s² = t² − x²（c = 1）、これはτ²に等しい', none: '何もない：すべての座標は基準系に依存する' }, explanation: 'ローレンツ変換で座標tとxは変わりますが、間隔s² = c²t² − x²は変わりません。宇宙船の世界線ではτ²に等しく、固有時間はすべての観測者に共通する世界線の幾何学的性質です。これが時空の中心的な考え方です。' },
  },
  'two-perspectives': {
    headlight: { question: '0.50cで進む宇宙船が前方へヘッドライトを点灯します。地球上の人は光の速さをいくらと測定しますか？', task: '「Headlight」を選び、宇宙船の速度を0.50c以上にして「Make the measurement」を押します。', options: { sum: '1.50c：宇宙船の速度が光速に加わる', c: '1.00c：光速と正確に同じ', half: '0.50c', 'bit-more': '1.00cより少し大きい' }, explanation: '光源の速さにかかわらず、測定値は常にcです。速度を単純に足すガリレイ的記述は1.50cを予測して失敗します。どちらの相対論的記述もcを予測します。ローレンツ速度合成でも、時空における光の世界線の間隔がゼロであることからも導けます。' },
    everyday: { question: '0.01c（3,000 km/s、ロケットよりはるかに速い速度）では、移動時計についてガリレイ的予測と相対論的予測の差はどの程度ですか？', task: '「Moving clock」を選び、0.01cなど0より大きく0.05c以下の速度で測定し、3つの予測を比較します。', options: { tiny: 'ごくわずか：約0.005%', one: '約1%', ten: '約10%', total: '完全に異なる' }, explanation: '相対論的な時計の遅れの割合は1 − 1/γ ≈ v²/2c²です。0.01cでは0.00005（0.005%）で、日常の速度ではさらに小さくなります。だからニュートン力学は日常生活でよく成り立ちます。ガリレイ的記述は相対論の低速極限です。' },
    simultaneity: { question: '地球系で10光秒離れた2つの地点に、同時に雷が落ちます。宇宙船は0.60cで前方の雷に向かって通過します。宇宙船からはどちらが先に落ちたように見えますか？', task: '「Two flashes」を選び、0.30c以上に設定して測定します。', options: { same: 'どちらでもない：依然として同時', front: '前方の雷（宇宙船が向かう側）', rear: '後方の雷', position: '落雷時の宇宙船の位置による' }, explanation: '宇宙船系では前方の閃光がγvΔx/c²だけ早く起こり、0.60cでは7.5秒です。同時性は相対的です。これは光が宇宙船に届く時間ではなく、同期された時計が遠方の事象をいつと判定するかの違いです。' },
    equivalence: { question: '「ローレンツ変換で結ばれた空間＋時間」と「時空」の記述で、異なる測定結果を予測するものはありますか？', task: '3つすべてのシナリオを0.50c以上で測定し、2つの記述の列を比較します。', options: { fast: 'はい、光速に近い速度で', simultaneity: 'はい、時空だけが説明できる同時性について', none: 'いいえ：同じ理論の2つの定式化です', dimension: 'はい：時空は検出可能な第4の空間次元を予測します' }, explanation: '両者は必ず一致します。ローレンツ変換は時空計量を保つ双曲回転です。測定可能な予測は、選んだ基準系の座標からでも不変量からでも計算でき、結果は一致します。異なるのは基本として提示する数学的な見方であり、物理的な予測ではありません。' },
  },
  'gravity-clocks': {
    mountain: { question: '1台の時計を海面に、同じ時計を海抜8.8 kmのエベレスト山頂に置きます。しばらくすると、どちらがより多くの時間を刻みますか？', task: '地球を選び、時計Aを海面、時計Bをエベレストに置いて、少なくとも1日動かします。', options: { sea: '海面の時計', everest: 'エベレストの時計', same: 'どちらでもない：同期したまま', depends: '観測者による' }, explanation: '重力場の深い場所にある時計ほど遅く進みます。エベレストの時計は海面の時計より1日あたり約83ナノ秒多く進みます。心拍や化学反応も同じ割合で進むため、本人は感じません。時計を比較して初めて違いが分かります。' },
    gps: { question: 'GPS衛星は高度20,200 kmを約3.9 km/sで周回します。地上の時計と比べると、衛星の時計はどう進みますか？', task: '「GPS satellite」に切り替え、少なくとも1日時計を動かします。', options: { fast: '1日あたり約38マイクロ秒速く進む', slow: '速く動くため遅く進む', same: 'まったく同じ速度で刻む', second: '1日あたり約1秒速く進む' }, explanation: '2つの効果が競合します。重力が弱い高高度では1日あたり約45.7 μs進み、軌道速度による時間の遅れで約7.2 μs遅れます。重力の効果が勝り、正味では約38.5 μs/日速く進みます。' },
    uncorrected: { question: 'GPSは信号の到着時間から位置を計算します。相対論を無視した場合、位置はどれほど速くずれていきますか？', task: '「GPS satellite」で相対論補正をオフにし、少なくとも1日動かします。', options: { metre: '1日あたり約1 m', km: '1日あたり約10 km', mm: '1日あたり約1 mm', none: '影響は小さすぎて、ずれない' }, explanation: '光は1マイクロ秒で約300 m進みます。1日あたり38.5 μsの時計誤差は、約11.5 km/日の距離誤差になります。そのため衛星時計は打ち上げ前に調整され、軌道上で地上から見た正しい速度で進むようにします。' },
    horizon: { question: '時計をブラックホールの事象の地平面へゆっくり近づけます。遠方の時計と比べて、非常に近づくと時計の進み方はどうなりますか？', task: 'ブラックホールを選び、時計Aを地平面の0.01 r_s上、またはそれより近くに置いて動かします。', options: { zero: 'ゼロに近づく', half: '半分になり、そのまま', backwards: '逆向きに進む', faster: '速くなる' }, explanation: '半径rで静止する時計は遠方の時計の√(1 − r_s/r)倍の速さで進み、地平面でゼロに近づきます。しかし時計自身にとって時間が止まるわけではありません。自由落下する時計は有限の固有時間で地平面を通過します。「時間が止まる」は遠方の時計との比較です。' },
    agree: { question: '「異なる時計」では、互いに動く観測者が相手の時計を遅いと判断しました。ここでは低い時計と高い時計の観測者は、どちらが遅いかについて一致しますか？', task: '異なる高さに2台の時計を置いて少なくとも1日動かし、「signals received」の表示を比較します。', options: { agree: 'はい：両者とも低い時計が遅いと判断する', mutual: 'いいえ：互いに相手の時計が遅いと判断する', unknowable: 'どちらにも分からない', frame: '基準系による' }, explanation: '両者は一致します。上向きに送られた刻みは赤方偏移して遅く届き、下向きの刻みは青方偏移して速く届きます。低い時計は高い観測者から遅く見え、高い時計は低い観測者から速く見えます。状況は対称ではなく、一方の時計が重力井戸の深い場所にあります。' },
  },
  'evolving-space': {
    centre: { question: '天文学者は、遠方銀河があらゆる方向で私たちから遠ざかるのを観測します。膨張の中心はどこですか？', task: '端に近い銀河をクリックして「home」にし、モデルを少なくとも20億年進めて矢印を観察します。', options: { us: '私たちの銀河', far: '遠くにある特別な一点', none: '中心はない：どの銀河からも他の銀河が遠ざかって見える', edge: '宇宙の端' }, explanation: '共動するどの銀河から見ても、大規模なパターンは同じです。束縛されていない共動銀河間の固有距離が増加します。スケール因子a(t)は時空幾何の変化を表し、銀河を運ぶ物質ではありません。ビッグバンは既存の空間中の一点で起きた爆発ではありません。' },
    bound: { question: '空間が膨張すると、銀河そのもの（地球やあなたも）も膨張しますか？', task: 'モデルを前後いずれかに少なくとも50億年進め、銀河の大きさと銀河間の隙間を比較します。', options: { all: 'はい：宇宙とともにすべてが大きくなる', bound: 'いいえ：重力などの力で束縛された物体の大きさは保たれる', galaxies: '銀河は大きくなるが惑星はならない', shrink: '隙間が広がるにつれて縮む' }, explanation: 'FLRWスケール因子は宇宙論的スケールで共動する物体間の固有距離の変化を表します。重力で束縛された銀河や電磁相互作用で束縛された原子は膨張しません。天の川銀河、太陽系、人間は宇宙のスケール因子に合わせて大きくなりません。' },
    faster: { question: '物体が空間内を光より速く移動することはできません。遠方銀河が光速より速く私たちから遠ざかることはありますか？', task: '現在の宇宙モデルで遠方銀河の距離を増やし、後退速度がcに達するところを確認します。', options: { never: 'いいえ、決してない', yes: 'はい、十分遠ければ相対論に反せず起こり得る', past: '遠い過去に限られる', engines: '銀河自体が高速で動く場合だけ' }, explanation: 'FLRWの後退率v = Hdは、ハッブル距離c/Hより遠方でcを超えることがあります。これは遠く離れた共動観測者間の固有距離の変化率であり、局所的な速度ではありません。局所的には、どの観測者も近くの光をcで測定します。' },
    age: { question: '宇宙年齢の単純な推定値は1/H₀ ≈ 145億年です。物質とダークエネルギーを含むフリードマン方程式ではどうなりますか？', task: '「Our universe」を選び、ビッグバンまで時間を戻して、そこから現在までの時間を読みます。', options: { same: '正確に1/H₀：145億年', planck: '約138億年', matter: '約96億年（1/H₀の2/3）', infinite: '無限に古い' }, explanation: '宇宙年齢はt₀ = ∫ da / (a H(a)) ≈ 138億年です。物質は過去の膨張を減速させ、ダークエネルギーは後期に加速させます。そのため単純な1/H₀とは異なります。物質だけの宇宙なら約96億年となり、最古の恒星より若くなってしまいます。' },
    acceleration: { question: '私たちの宇宙では、膨張が減速から加速へ切り替わったのはいつですか？', task: '宇宙史の中頃を通してモデルを動かし、「Expansion is…」の表示と減速パラメーターqを観察します。', options: { always: '最初からずっと加速している', six: '約60億年前', never: 'まだ切り替わっておらず、減速中', start: 'ビッグバンの直後' }, explanation: '放射、物質、ダークエネルギーが切り替わりを決めます。このモデルではq = 0となるスケール因子は約0.609、赤方偏移は約0.642で、約61.4億年前です。宇宙膨張の加速は1998年に遠方超新星の観測から発見されました。' },
  },
  'force-lab': {
    'held': { question: "5 kg のブロックが水平な床の上で静止しています。横向きに 10 N で押しても動きません。ブロックに働く摩擦力の大きさはいくらですか。", task: "水平面で、ブロックが静止したままになる小さな力で押して試行を実行し、摩擦力を読み取ってください。", options: {"zero": "ゼロ：何も動いていないので摩擦はない", "equal": "10 N：押す力とちょうどつり合う", "maximum": "最大値 μsN", "larger": "10 N より大きい（そうでなければ動いてしまう）"}, explanation: "ブロックは静止しているので合力はゼロであり、摩擦力は押す力をちょうど打ち消す 10 N でなければなりません。静止摩擦力は決まった値ではありません。滑りを防ぐのに必要な大きさになり、その上限が μsN です。強く押すほど摩擦力も大きくなり、上限に達するまで増え続けます。" },
    'breakaway': { question: "押す力を大きくしていくと、やがてブロックが滑り始めます。滑っている間の摩擦力は…", task: "ブロックと面を同じにしたまま、ブロックが静止する試行と、滑り出すほど強く押す試行を一つずつ行い、摩擦力を比べてください。", options: {"larger": "最大の静止摩擦力より大きい", "smaller": "小さい：動摩擦力 μkN は静止摩擦の最大値 μsN より小さい", "same": "静止摩擦の最大値とまったく同じ", "zero": "ブロックが動き出したのでゼロ"}, explanation: "ブロックが滑り始めると、摩擦力は動摩擦力 μkN になります。多くの面では、これは静止摩擦の最大値 μsN より小さくなります。重い箱を動かし始めるときのほうが、動かし続けるときより強く押す必要があるのはこのためです。動摩擦力は押す力に応じて増えないので、余分な力は加速度になります。" },
    'incline-normal': { question: "30° の斜面上でブロックが静止しています。重さ mg と比べて、面からの垂直抗力は…", task: "15° 以上の斜面を選んで試行を実行し、垂直抗力と重さを比べてください。", options: {"equal": "mg に等しい：面は常に重さ全体を支える", "cos": "小さい：mg cos θ", "sin": "小さい：mg sin θ", "larger": "mg より大きい"}, explanation: "面は自分に垂直な向きに押すので、垂直抗力は重さのうち面に向かう成分だけを打ち消せばよく、N = mg cos θ となります（30° では重さの 87 %）。残りの成分 mg sin θ は斜面に沿って下向きです。最大摩擦力は μsN なので、斜面が急になるほど摩擦の上限も小さくなります。" },
    'mass-independence': { question: "押す力がない状態で、同じ材質の軽いブロックと重いブロックが同じ斜面上で静止しています。斜面の角度を大きくしていくと、先に滑り始めるのはどちらですか。", task: "押す力を 0 N にした斜面で、角度と摩擦係数を同じにして、質量の異なる二つの試行を行ってください。滑り始める角度の前後で試してみましょう。", options: {"heavy": "重いブロック：重さが斜面に沿って強く引くから", "light": "軽いブロック：支える摩擦が小さいから", "same": "どちらも同じ角度、tan θ = μs のとき", "never": "どちらも滑らない：摩擦は静止したブロックを常に支える"}, explanation: "斜面に沿って下向きに引く力 mg sin θ と摩擦の上限 μs mg cos θ はどちらも質量に比例するので、質量は打ち消し合います。質量に関係なく tan θ > μs で滑り始めます（μs = 0.40 なら約 21.8°）。滑り始めた後の加速度 a = g(sin θ − μk cos θ) も質量によりません。滑り始める角度を測ることは、μs を測定する標準的な方法です。" },
  },
  'length-contraction': {
    'moving': { question: "長さ 10 m の宇宙船が 0.8c で地球のそばを通過します。地球の観測者は、地球の同じ時刻に前端と後端の位置を記録します。測定される長さはいくらですか。", task: "速さを 0.5c 以上にして測定を実行し、測定長 L と固有長 L₀ を比べてください。", options: {"same": "同じ 10 m", "shorter": "10 m より短い", "longer": "10 m より長い", "zero": "ゼロ：速すぎて測定できない"}, explanation: "地球の観測者は L = L₀/γ を測定します。0.8c では γ = 1.667 なので、10 m の宇宙船は 6 m と測定されます。宇宙船が押し縮められているわけではありません。宇宙船自身の静止系では長さは 10 m のままで、これが固有長です。二つの基準系は、どの両端の事象の組が「同時」に起きたかについて一致しないため、長さについても一致しないのです。" },
    'rest': { question: "同じ宇宙船が地球のそばに停泊し、地球の観測者に対して静止しています。このとき測定される長さはいくらですか。", task: "相対速度を 0 にして測定を実行してください。", options: {"proper": "固有長の 10 m", "shorter": "まだ 10 m より少し短い", "longer": "10 m より長い"}, explanation: "相対運動がなければ、地球と宇宙船は同じ基準系にあり、「同時」の意味について一致するので、地球は固有長の 10 m を測定します。長さの収縮は宇宙船の恒久的な変化ではありません。物体と測定者の間の相対速度だけで決まります。" },
    'doubling': { question: "宇宙船の速さが 0.4c から 0.8c へ 2 倍になります。縮む量 L₀ − L はどう変わりますか。", task: "固有長を変えずに、0.40c と 0.80c で測定し、表の長さの差を比べてください。", options: {"double": "速さと同じく 2 倍になる", "five": "ほぼ 5 倍になる", "same": "変わらない", "half": "半分になる"}, explanation: "L = L₀√(1 − v²/c²) は v について線形からほど遠い式です。0.4c では 10 m の宇宙船は 0.83 m 縮み、0.8c では 4 m と、ほぼ 5 倍縮みます。低速では L₀ − L ≈ L₀v²/(2c²) なので縮みは速さの 2 乗に比例し、c に近づくとさらに急に増えます。日常の速さでこの効果に気づかないのはこのためです。" },
    'simultaneity': { question: "地球は地球の同じ時刻に後端と前端を記録します。宇宙船の基準系では、この二つの記録の事象は同時ですか。", task: "0 でない任意の速さで測定を実行し、宇宙船の基準系での両端の事象の時間差を読み取ってください。", options: {"yes": "はい：同時の事象は誰にとっても同時", "front": "いいえ：前端が vL₀/c² だけ先に記録される", "rear": "いいえ：後端が vL₀/c² だけ先に記録される"}, explanation: "ローレンツ変換により、Δt = 0 のとき Δt′ = γ(Δt − vΔx/c²) = −vL₀/c² となります。宇宙船の基準系では前端が先に記録されるのです。宇宙船から見ると、地球は両端を同時に記録していないので、地球の結果は宇宙船の基準系での長さではなく、L₀ と等しい必要もありません。長さの収縮とは、物体の両端に同時性の相対性を当てはめたものなのです。" },
  },
  'momentum-collisions': {
    'swap': { question: "台車 1 が 4 m/s で、静止している同じ台車 2 にぶつかります。衝突は弾性衝突（e = 1）です。その後どうなりますか。", task: "2 台の質量を同じにし、台車 2 の速度を 0、台車 1 の速度を正にしてください。e = 1 にして衝突を実行し、衝突後の速度を読み取りましょう。", options: {"swap": "台車 1 が止まり、台車 2 が 4 m/s で動き出す", "share": "2 台が一緒に 2 m/s で進む", "bounce": "台車 1 が 4 m/s で跳ね返る", "both-move": "2 台とも前に進み、台車 2 が少し速い"}, explanation: "運動量は 8 kg·m/s のままでなければならず、弾性衝突では運動エネルギーも保存されなければなりません。質量が等しい場合、両方を満たす唯一の方法は 2 台が速度を交換することです。台車 1 は止まり、台車 2 が 4 m/s で進みます。ビリヤードの球やニュートンのゆりかごでも同じことが見られます。" },
    'stick': { question: "同じ 2 台の台車が、今度は衝突するとくっつきます（e = 0）。衝突後の速さはどうなりますか。", task: "質量を等しく、台車 2 を静止させたまま e = 0 にして、衝突を実行してください。", options: {"same": "台車 1 の最初の速さ", "half": "台車 1 の最初の速さの半分", "stop": "止まる", "quarter": "台車 1 の最初の速さの 4 分の 1"}, explanation: "運動量はやはり保存されます。m·u = 2m·v なので、2 台は台車 1 の速さの半分で進みます。ここでは運動エネルギーは保存されません。その半分が熱、音、台車の変形に変わります。運動量保存から衝突後の速さはわかりますが、どれだけのエネルギーが残るかはわかりません。" },
    'conserved': { question: "e = 0.5 の衝突で、衝突の前後で変わらない量はどれですか。", task: "反発係数を 0 と 1 の間に設定して衝突を実行し、衝突前後の運動量と運動エネルギーを比べてください。", options: {"momentum": "全運動量だけ", "energy": "全運動エネルギーだけ", "both": "運動量と運動エネルギーの両方", "neither": "どちらも変わる"}, explanation: "衝突の間、2 台は大きさが等しく向きが反対の力を同じ時間だけ及ぼし合うので、力積は打ち消し合い、e の値に関係なく全運動量は変わりません。運動エネルギーが保存されるのは e = 1 のときだけです。0 < e < 1 では一部が内部エネルギーに変わり、その減少量は ΔK = ½μ(1 − e²)(u₁ − u₂)² です。" },
    'heavy-light': { question: "4 m/s で進む 10 kg の台車が、静止している 1 kg の台車に弾性衝突します。衝突後の軽い台車の速さに最も近いのは…", task: "台車 1 を台車 2 の 5 倍以上重くし、台車 2 を静止させ、e = 1 にして衝突を実行してください。", options: {"same": "4 m/s：重い台車と同じ速さ", "double": "7.3 m/s：重い台車のほぼ 2 倍の速さ", "small": "0.4 m/s", "forty": "40 m/s：運動量をすべて受け取る"}, explanation: "重心系では、弾性衝突は各速度の向きを反転させるだけです。重心は 40/11 ≈ 3.6 m/s で動くので、軽い台車は重心に対して −3.6 m/s で近づき +3.6 m/s で離れます。実験室系では 7.3 m/s、すなわち v₂ = 2m₁u₁/(m₁ + m₂) です。m₁/m₂ が大きくなるほど、軽い台車の速さは重い台車の速さの 2 倍に近づきます。探査機が惑星のそばを通る重力スイングバイも同じ考え方を利用しています。" },
  },
  'circular-orbits': {
    'direction': { question: "人工衛星が一定の速さで地球の周りを円運動しています。衛星に働く合力はどちらを向いていますか。", task: "打ち上げの速さをちょうど 1.00 × 円軌道の速さにして打ち上げ、衛星に描かれた力の矢印を見てください。", options: {"centre": "円の中心向き", "forward": "前向き（運動の向き）", "outward": "外向き（中心から離れる向き）", "none": "速さが一定なので合力はない"}, explanation: "速さは変わりませんが、運動の向きが曲がり続けるので速度は変化し、衛星は加速しています。その加速度 v²/r は中心を向いており、合力 m v²/r も中心を向いています。衛星の場合、その力は重力です。前に押すものはありません。衛星が動き続けるのは、止めるものがないからです。" },
    'faster': { question: "今度は同じ場所から、円軌道の速さより少しだけ速く衛星を打ち上げます。どのような経路をたどりますか。", task: "1.05～1.35 × 円軌道の速さで打ち上げ、経路を円と比べてください。", options: {"ellipse": "反対側でより遠くまで膨らみ、打ち上げ地点に戻ってくる楕円", "bigger": "より大きな円", "escape": "宇宙へ飛び去る", "spiral": "どんどん広がるらせん"}, explanation: "速くなった経路を重力が円に曲げきれないので、衛星は上昇します。上昇するにつれて遅くなり、やがて重力がまさって打ち上げ地点に落ちて戻ります。この地点が楕円の最も近い点になります。円軌道の速さより遅く打ち上げた場合は、打ち上げ地点が最も遠い点になります。どちらの場合も軌道は閉じてそのまま繰り返します。ニュートンの重力では、束縛された軌道は閉じた楕円です。" },
    'kepler': { question: "円軌道を地球半径の2倍から4倍の距離へ移します。周期は…", task: "半径が1.5倍以上異なる2つの円軌道（1.00 × 円軌道の速さ）を実行し、周期を比べてください。", options: {"cube": "約2.8倍になる", "double": "2倍になる", "same": "変わらない", "half": "重力が弱くなるので半分になる"}, explanation: "経路の長さは2倍になり、円軌道の速さ √(GM/r) は √2 分の1になるので、周期 T = 2πr/v は 2 × √2 ≈ 2.8 倍になります。一般に T² ∝ r³ で、これはケプラーが惑星のデータから見つけ、ニュートンが重力と円運動で説明したケプラーの第3法則です。" },
    'escape': { question: "衛星が二度と戻ってこないようにするには、その高さでの円軌道の速さと比べて、どれだけの速さで打ち上げる必要がありますか。", task: "境目を見つけましょう。1.2 × 円軌道の速さ以上でまだ戻ってくる軌道と、脱出する打ち上げをそれぞれ1回ずつ実行してください。", options: {"root2": "円軌道の速さの √2 ≈ 1.41 倍", "two": "円軌道の速さの2倍", "any": "円軌道の速さより速ければどんな速さでもよい", "never": "いずれは必ず戻ってくる"}, explanation: "運動エネルギーで重力の井戸から抜け出す分をまかなえれば、衛星は脱出します。½v² − GM/r ≥ 0 より v ≥ √(2GM/r) = √2 · v_c です。ちょうど √2 倍なら経路は放物線、それより速ければ双曲線になります。脱出速度は出発点だけで決まり、向きにはよりません（経路が惑星にぶつからない限り）。" },
  },
  'geodesic-motion': {
    'perturbed': { question: "宇宙船がブラックホールの周りを 8 rₛ で回っていますが、角運動量は円軌道に必要な値より少しだけ小さくなっています。何周かした後、経路はどのようになりますか。", task: "8 rₛ 以上から、角運動量を 1 × L 円軌道から少しずらして実験を実行し、二つの経路を比べてください。", options: {"circle": "円", "ellipse": "同じ閉じた楕円を何度もたどる", "precess": "最も近い点が一周ごとに少しずつ回っていく楕円", "spiral": "ブラックホールへ落ち込むらせん"}, explanation: "ニュートン重力では、軌道は正確に繰り返す閉じた楕円になります（破線の経路）。シュワルツシルト時空では、最も近い点である近点が一周ごとに進み、経路はロゼット模様を描きます。太陽の周りを回る水星の軌道も、ごくゆっくりですが同じように振る舞います。これを説明したことは一般相対性理論の最初の成功の一つでした。" },
    'circular': { question: "今度は、宇宙船に円軌道とちょうど同じ角運動量を与え、内向き・外向きの速度はゼロにします。どのような経路をたどりますか。", task: "角運動量を 1.000 × L 円軌道、動径速度を 0 にして実験を実行してください。", options: {"circle": "円", "precess": "ゆっくり回転する楕円", "spiral": "ブラックホールへ落ち込むらせん"}, explanation: "シュワルツシルト時空にも円軌道は存在します。角運動量がちょうど適切で動径方向の運動がなければ半径は変わらず、移動する近点もありません。歳差運動が現れるのは、軌道が完全な円でないときだけです。3 rₛ より内側では円軌道でさえ不安定になり、わずかな乱れで宇宙船は落ち込んでしまいます。" },
    'distance': { question: "わずかに楕円の軌道をブラックホールから遠ざけ、5 rₛ から 12 rₛ にします。一周あたりの近点移動は…", task: "角運動量と動径速度を変えずに、3 rₛ 以上離れた二つの初期半径で一周あたりの移動量を測定してください。", options: {"grows": "大きくなる", "shrinks": "小さくなる", "same": "変わらない", "reverses": "向きが逆になる"}, explanation: "動径方程式の相対論的な項 −3L²/(2r⁴) は、ニュートンの項 −1/(2r²) より速く小さくなるので、軌道が遠いほど閉じたニュートンの楕円に近づきます。ほぼ円の軌道では移動量は約 360°·(1/√(1 − 3rₛ/r) − 1) で、5 rₛ では一周あたり約 210°、12 rₛ では 56° です。これがニュートン極限です。" },
    'mercury': { question: "質量から遠い所では、一周あたりの移動量は約 3π rₛ/r ラジアンです。水星は太陽から約 2 × 10⁷ rₛ の所を回っています。水星の近点の一周あたりの移動量はおよそ…", task: "まず弱い重力場での見積もりを確かめましょう。10 rₛ 以上で、ほぼ円の軌道（角運動量が 1 から 0.01 以内、動径速度なし）を実行し、測定した移動量を見積もりと比べてください。", options: {"arcsec": "約 0.1 秒角", "degree": "約 1 度", "radian": "約 0.5 ラジアン", "zero": "ちょうどゼロ：太陽の重力は相対論には弱すぎる"}, explanation: "3π/(2 × 10⁷) ≈ 5 × 10⁻⁷ rad ≈ 一周あたり 0.1″ です。水星は 1 世紀に約 415 周するので、1 世紀あたり 43″ になります。これはニュートン重力では説明できず、1915 年にアインシュタインが計算した異常です。同じ式は 12 rₛ では約 45° を与えますが、そこではほぼ円軌道の厳密な結果、約 56° のほうがすでに明らかに大きくなっています。" },
  },
}

export function localizePredictions<T extends { readonly id: string; readonly question: string; readonly task: string; readonly options: readonly { readonly id: string; readonly label: string }[]; readonly explanation: string }>(experiment: ExperimentId, predictions: readonly T[], locale: Locale): T[] {
  if (locale === 'en') return [...predictions]
  const catalogue = (locale === 'id' ? id : ja)[experiment]
  return predictions.map((prediction) => {
    const copy = catalogue[prediction.id]
    if (!copy) return prediction
    return {
      ...prediction,
      question: copy.question,
      task: copy.task,
      options: prediction.options.map((option) => ({ ...option, label: copy.options[option.id] ?? option.label })),
      explanation: copy.explanation,
    } as T
  })
}
